// Normalize & Score
// Normaliza el payload entrante y conserva campos HNWI relevantes
// para que el backend Nexus pueda calcular/recibir score, tier y email_verified.

const input = items[0]?.json || {};
const body = input.body || input;

// Helpers
function asString(value, fallback = undefined) {
  if (value === null || value === undefined || value === '') return fallback;
  return String(value).trim();
}

function asNumber(value, fallback = undefined) {
  if (value === null || value === undefined || value === '') return fallback;
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function asBoolean(value, fallback = false) {
  if (value === true || value === 'true' || value === 1 || value === '1') return true;
  if (value === false || value === 'false' || value === 0 || value === '0') return false;
  return fallback;
}

function cleanObject(obj) {
  return Object.fromEntries(
    Object.entries(obj).filter(([_, value]) => value !== undefined)
  );
}

// Source mapping
const source_system = asString(body.source_system, 'manual');
const source_channel = asString(body.source_channel, 'other');
const connector_name = asString(
  body.connector_name,
  source_system && source_channel
    ? `${source_system}:${source_channel}`
    : 'manual:intake'
);
const source_detail = asString(body.source_detail, 'n8n_unified_intake');

// Text/classification
const text = [
  body.notes,
  body.property_interest,
  body.hnwi_intent_signal,
  body.zone_interest,
  body.nationality,
  body.source_detail,
].filter(Boolean).join(' ');

let classification = 'Unknown';

if (/sell|propietario|vender|valoraci|owner/i.test(text)) {
  classification = 'Seller';
} else if (/buy|comprar|inversi|search|busco|looking|interested/i.test(text)) {
  classification = 'Buyer';
}

if (/luxury|premium|hnwi|family office|off-market|private client|high net worth/i.test(text)) {
  classification = 'HNWI';
}

// Local fallback scoring
const budget = asNumber(body.budget);

let score = 0;

if (budget !== undefined) {
  if (budget >= 2000000) score += 40;
  else if (budget >= 1000000) score += 30;
  else if (budget >= 500000) score += 20;
}

if (classification === 'HNWI') score += 30;

if (/andratx|calvià|calvia|son vida|bendinat|portals|deià|deia|valldemossa/i.test(text)) {
  score += 15;
}

if (/looking to buy|busco|comprar|interested in|off-market|villa buyer|family office/i.test(text)) {
  score += 15;
}

if (asBoolean(body.gdpr_consent, false)) score += 10;

score = Math.max(0, Math.min(score, 100));

let tier = 'cold';
if (score >= 70) tier = 'hot';
else if (score >= 40) tier = 'warm';

// Preserve upstream values when present.
// This is critical for HNWI tests and upstream workflows.
const qualification_score =
  body.qualification_score !== undefined && body.qualification_score !== null
    ? asNumber(body.qualification_score, score)
    : score;

const qualification_tier =
  asString(body.qualification_tier) || tier;

const email_verified = asBoolean(body.email_verified, false);

// IDs and traceability
const email = asString(body.email);
const phone = asString(body.phone);
const source_url = asString(body.source_url || body.linkedin_profile_url || body.profile_url);

const external_id = asString(
  body.external_id ||
  body.linkedin_member_id ||
  source_url ||
  email ||
  phone ||
  `lead-${Date.now()}`
);

const metadata = {
  ...(body.metadata || {}),
  classification,
  workflow: 'n8n-unified-lead-intake',
  origin_workflow:
    body.metadata?.origin_workflow ||
    body.origin_workflow ||
    source_detail,
  captured_at_n8n: new Date().toISOString(),
};

// Final Nexus-compatible payload
const payload = cleanObject({
  org_id: asString(body.org_id, '9d6cb56d-3f21-4f7b-80ea-797a7c2c62cf'),

  external_id,
  connector_name,
  source_system,
  source_channel,
  source_detail,

  source_url,
  source_referrer: asString(body.source_referrer),

  gdpr_consent: asBoolean(body.gdpr_consent, false),
  gdpr_consent_at: asString(body.gdpr_consent_at),
  gdpr_consent_text_version: asString(body.gdpr_consent_text_version, 'v1'),

  name: asString(body.name, 'Anonymous Lead'),
  email,
  phone,
  budget,
  property_interest: asString(body.property_interest),
  notes: asString(body.notes),

  nationality: asString(body.nationality),
  zone_interest: asString(body.zone_interest),

  qualification_score,
  qualification_tier,

  hnwi_intent_signal: asString(body.hnwi_intent_signal),
  email_verified,
  email_verification_source: asString(body.email_verification_source),
  hnwi_source_channel: asString(body.hnwi_source_channel, source_channel),

  metadata,
});

return [
  {
    json: payload,
  },
];

const nexus = $('Nexus API Request').item.json;
const normalized = $('Normalize & Score').item.json;

const tier = nexus.qualification_tier;
const emailVerified = nexus.email_verified === true;
const connectorName = normalized.connector_name || '';
const isHnwi = connectorName.startsWith('hnwi-prospection');

const shouldNotify =
  tier === 'hot' ||
  (tier === 'warm' && emailVerified && isHnwi);

return [
  {
    json: {
      ...nexus,
      connector_name: connectorName,
      should_notify_internal: shouldNotify,
      notification_reason:
        tier === 'hot'
          ? 'hot_lead'
          : shouldNotify
            ? 'warm_hnwi_email_verified'
            : 'no_notification'
    }
  }
];
